package medium;public class FourSum{public static java.util.List<java.util.List<Integer>>fourSum(int[]n,int t){java.util.List<java.util.List<Integer>>r=new java.util.ArrayList<>();java.util.Arrays.sort(n);int l=n.length;for(int i=0;i<l-3;i++){if(i>0&&n[i]==n[i-1])continue;for(int j=i+1;j<l-2;j++){if(j>i+1&&n[j]==n[j-1])continue;int a=j+1,b=l-1;while(a<b){long s=(long)n[i]+n[j]+n[a]+n[b];if(s==t){r.add(java.util.Arrays.asList(n[i],n[j],n[a],n[b]));while(a<b&&n[a]==n[a+1])a++;while(a<b&&n[b]==n[b-1])b--;a++;b--;}else if(s<t)a++;else b--;}}}return r;}public static void main(String[]args){System.out.println("4Sum works\n");}}
